package com.abhinav.taskwall.data

import kotlinx.coroutines.flow.Flow

class QuoteRepository(private val quoteDao: QuoteDao) {

    suspend fun getNextEligibleQuote(): Quote? {
        return quoteDao.getNextEligibleQuote()
    }

    suspend fun getQuoteById(id: Long): Quote? {
        return quoteDao.getQuoteById(id)
    }

    fun getAllQuotes(): Flow<List<Quote>> {
        return quoteDao.getAllQuotes()
    }

    suspend fun markQuoteAsShown(quoteId: Long) {
        val quote = quoteDao.getQuoteById(quoteId)
        if (quote != null) {
            quoteDao.updateQuote(quote.copy(lastShownAt = System.currentTimeMillis()))
        }
    }

